const TEV_FRAMES=["/gotu/mirror-demo-v9/assets/tev-frame-01.png", "/gotu/mirror-demo-v9/assets/tev-frame-02.png", "/gotu/mirror-demo-v9/assets/tev-frame-03.png", "/gotu/mirror-demo-v9/assets/tev-frame-04.png"];
let state=Model.initial(),view='about',focusId='reason',teamFilter='All teams',discussionStep=0,csvVisible=false,expandedSuggestion=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const main=document.querySelector('#main');
const btn=(text,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const groupOrder=()=>['Looking back',...(state.identity?.teams||[]),'Looking forward'];
const approvalCount=()=>state.answers.filter(Model.isApproved).length;
const selected=()=>state.answers.find(a=>a.id===focusId);
const status=a=>`<span class="pill ${Model.isApproved(a)?'green':''}">${Model.isApproved(a)?'Approved':'Needs approval'} · version ${a.version}</span>`;
function dispatch(action){state=Model.reduce(state,action);render();}
const BASE='/gotu/mirror-demo-v9';
const SLUGS={back:'looking-back',Executive:'executive',GTM:'gtm',forward:'looking-forward'};
let routeSection=null,countdown=5,countdownTimer=null,micTimer=null,videoTimer=null,videoTick=0,videoPlaying=false,modalStep='',selectedOutput=null,historyRender=false,chatTurns=[];
const routePath=()=>view==='interview'?BASE+'/interview/'+(routeSection||SLUGS[state.chapters[state.chapter]?.id]||'looking-back'):BASE+({about:'/about-demo',outcomes:'/outcomes',tev:'/for-tev',group:'/group-brief',guide:'/interview-guide',initializing:'/initializing',start:'/start',voice:'/voice-guide',welcome:'/form',review:'/review',chat:'/chat',complete:'/copy',sheet:'/sheet'}[view]||'');
const locationPath=()=>location.protocol==='file:'?(location.hash.slice(1)||BASE):location.pathname.replace(/\/$/,'');
function writeRoute(replace=false){const path=routePath();if(locationPath()===path)return;const url=location.protocol==='file:'?'#'+path:path;history[replace?'replaceState':'pushState']({},'',url);}
function stopCountdown(){clearInterval(countdownTimer);countdownTimer=null;}
function stopMedia(){clearInterval(micTimer);clearInterval(videoTimer);micTimer=null;videoTimer=null;videoPlaying=false;}
function closeOnboarding(){stopMedia();modalStep='';const d=document.querySelector('#onboarding-dialog');if(d.open)d.close();}
function guardedView(v){if(['interview','review','outcomes','tev','group','guide','chat','complete','sheet'].includes(v)&&!state.identity){state.notice='This demo keeps progress only in this tab. Add your facts to begin again.';return 'welcome';}if(v==='review'&&!state.finished)return 'interview';if(['outcomes','tev','group','guide','chat','complete','sheet'].includes(v)&&!Model.currentPackage(state))return state.finished?'review':'interview';return v;}
function navigate(v,replace=false){if(state.editing){document.querySelector('#toast').textContent='Save or cancel the open edit first.';document.querySelector('#edit-text')?.focus();return;}stopCountdown();closeOnboarding();routeSection=null;view=guardedView(v);if(view==='initializing')countdown=5;writeRoute(replace);render();main.focus();window.scrollTo(0,0);if(view==='initializing')startCountdown();}
function startCountdown(){stopCountdown();countdownTimer=setInterval(()=>{if(view!=='initializing'){stopCountdown();return;}countdown--;if(countdown===0){navigate('start',true);return;}const n=document.querySelector('#countdown');if(n)n.textContent=countdown;},1000);}
function readRoute(){stopCountdown();closeOnboarding();const path=locationPath();const leaf=path.startsWith(BASE)?path.slice(BASE.length):'';const map={'':'about','/about-demo':'about','/outcomes':'outcomes','/for-tev':'tev','/group-brief':'group','/interview-guide':'guide','/initializing':'initializing','/start':'start','/voice-guide':'voice','/form':'welcome','/review':'review','/chat':'chat','/copy':'complete','/sheet':'sheet'};let target=map[leaf];routeSection=null;if(leaf.startsWith('/interview/')){target='interview';routeSection=leaf.split('/')[2];}if(!target)target='about';if(state.editing&&target!==view){writeRoute(true);return;}view=guardedView(target);if(view==='interview'&&routeSection){const n=state.chapters.findIndex(c=>SLUGS[c.id]===routeSection);if(n<0||n>state.chapter)routeSection=null;}historyRender=true;writeRoute(true);if(view==='initializing')countdown=5;render();historyRender=false;main.focus();window.scrollTo(0,0);if(view==='initializing')startCountdown();}
window.addEventListener('popstate',readRoute);
function render(){
 if(view!=='initializing')stopCountdown();
 if(!historyRender)writeRoute();
 document.querySelector('.shell').classList.toggle('ftue',['about','initializing','start','voice','welcome','outcomes','tev','group','guide','chat'].includes(view));
 const prior=document.activeElement?.closest('button[data-action]');const priorAction=prior?.dataset.action,priorId=prior?.dataset.id;
 const available=[['about','01','About the demo'],['start','02','Welcome'],['welcome','03','Facts'],['interview','04','Interview'],['review','05','Review answers'],['outcomes','06','Two outcomes']];
 document.querySelector('#nav').innerHTML=available.map(([v,n,title])=>btn(`<span class="step-num">${n}</span>${title}`,'navigate',`data-view="${v}" ${((v==='interview'&&!state.identity)||(v==='review'&&!state.finished)||(['outcomes','tev','group','guide','chat','complete','sheet'].includes(v)&&!Model.currentPackage(state)))?'disabled':''} ${(view===v||(view==='answer'&&v==='review'))?'aria-current="step"':''}`)).join('');
 document.querySelector('#side-state').innerHTML=state.identity?`<p><strong>${esc(state.identity.name)}</strong><br>${esc(state.identity.teams.join(' · '))}</p><p>${state.finished?`${state.answers.length} answers · ${Model.currentPackage(state)?'approved':'final review'}`:'One interview · review at the end'}</p><p>${Model.currentPackage(state)?'Local package ready.<br>Nothing delivered.':'Your words are not a submission until you approve them.'}</p>`:'<p>One conversation.<br>A deliberate final review.<br>A useful planning handoff.</p>';
 main.innerHTML=({about:about,outcomes:outcomes,tev:forTev,group:groupBrief,guide:interviewGuide,initializing:initializing,start:startScreen,voice:voiceGuide,chat:afterChat,welcome:welcome,interview:interview,review:review,answer:answer,complete:complete,sheet:sheet}[view]||welcome)()+`<p id="toast" role="status" aria-live="polite">${esc(state.notice)}</p>`;
 updatePrint();
 const log=document.querySelector('.chat-scroll');if(log)log.scrollTop=log.scrollHeight;const personal=document.querySelector('.personal-log');if(personal)personal.scrollTop=personal.scrollHeight;
 if(priorAction){const target=[...main.querySelectorAll('button[data-action]')].find(b=>b.dataset.action===priorAction&&b.dataset.id===priorId&&!b.disabled);if(target)target.focus({preventScroll:true});}
}
function initializing(){return `<div class="initializing"><span class="eyebrow">GoTu · Mirror</span><h1>Initializing Mirror</h1><p class="lead">You’re about to experience the Mirror as a first-time user would.</p><div id="countdown" class="countdown" role="status" aria-live="polite">${countdown}</div><p class="small muted">The employee welcome opens automatically.</p>${btn('← Back to demo guide','navigate','data-view="about"','ghost')}</div>`;}
function startScreen(){return `<div class="welcome-editorial"><div class="experience-label">Participant experience · demo</div><div class="welcome-hero"><div class="welcome-copy"><p class="eyebrow">Your GoTu Quarterly Planning Mirror</p><h1>Let’s talk about<br>the quarter.<br><em>All of it.</em></h1><p class="lead">The wins. The friction. The things you’re still figuring out.</p><p><strong>Use dictation if you can.</strong> Think out loud, follow a thought, and add the example. That extra detail helps the Mirror ask better questions and capture what you actually mean.</p>${btn('Begin Mirror','begin-onboarding','','primary')}<p class="tiny muted">A quick voice check, a few tips, and Tev’s welcome—then we’ll get talking.</p></div></div><div class="welcome-bottom"><p><strong>Something for you, too.</strong> After submitting, explore a takeaway or prepare a question you want to bring into the room.</p><span class="tiny muted">Scripted demo · no recording or delivery</span></div></div>`;}
function voiceGuide(){return `<div class="voice-guide-page"><div class="experience-label">Participant experience · before Tev’s welcome</div><div class="welcome-note mic-note"><span class="voice-symbol" aria-hidden="true">❙ ❚ ❙ ❚ ❙</span><p class="eyebrow">Built for speaking, thinking, and discovery</p><h2>Use voice.<br>Go beyond the<br>first answer.</h2><p>Tell the story. Say what you’re unsure about. Let one thought lead to another. The context, nuance, and unexpected connections are what make this conversation valuable.</p><div class="note-rule"><b>Keep talking. The Mirror will help.</b><p>You can pause, ramble, or change your mind. Follow-up questions help you go deeper; you’ll shape the final answers afterward.</p></div><div class="note-rule"><b>You decide what leaves the conversation.</b><p>Review the complete draft together. Edit anything. Only the exact answers you approve become your planning submission.</p></div><div class="voice-guide-action"><span class="small">Next, watch Tev’s short welcome.</span>${btn('Continue to Tev’s welcome →','voice-next','','primary')}</div></div></div>`;}
function showOnboarding(html){const d=document.querySelector('#onboarding-dialog');d.innerHTML=html;if(!d.open)d.showModal();d.querySelector('button')?.focus();}
function openMic(){stopMedia();modalStep='mic';showOnboarding(`<button class="dialog-close ghost" data-action="close-onboarding" aria-label="Close voice check">×</button><p class="eyebrow">Before we talk</p><h2 id="dialog-title">Try voice input</h2><p>Find a quiet spot where you can speak freely. Headphones can help.</p><ol class="mic-steps"><li>Start the quick check.</li><li>Read the short phrase out loud.</li><li>Then review two conversation tips.</li></ol><p class="notice small">Simulated voice check. This demo won’t request microphone access or record you.</p>${btn('Start test · simulated','mic-test','','primary wide')}<div class="row spacer center">${btn('Skip voice check','mic-skip','','ghost')}</div>`);}
function runMic(){stopMedia();modalStep='mic-running';showOnboarding(`<p class="eyebrow">Simulated · no recording</p><h2 id="dialog-title">Try thinking out loud.</h2><p>Read this phrase at your own pace:</p><blockquote>I can take my time, think out loud, and choose what I share.</blockquote><div class="wave" aria-hidden="true">${Array.from({length:19},(_,i)=>`<i style="--bar:${12+(i%5)*5}px"></i>`).join('')}</div><p id="mic-state" class="small muted" role="status">Showing a sample voice check…</p>${btn('Continue →','mic-stop','','primary wide')}`);micTimer=setTimeout(()=>{if(modalStep==='mic-running'){document.querySelector('#mic-state').textContent='Demo check complete. No audio was captured.';}},2500);}
const INTRO_COPY=['Make room for the detail behind your answers.','Talk about what’s working, what’s difficult, and what you want to change.','You’ll review everything and choose exactly what goes into planning.','Keep something useful for yourself: your takeaways and questions for the room.'];
function openVideo(){stopMedia();modalStep='video';videoTick=0;showOnboarding(`<button class="dialog-close ghost" data-action="close-onboarding" aria-label="Close introduction">×</button><p class="eyebrow">A welcome from your planning facilitator · mock introduction</p><h2 id="dialog-title">Your voice matters in planning.</h2><div class="tev-video"><img id="tev-frame" src="${TEV_FRAMES[0]}" alt="Planning facilitator, shown in a supplied still image"><span class="video-label">MOCK VIDEO · SILENT STILL SEQUENCE</span><p id="video-caption">${INTRO_COPY[0]}</p></div><div class="row between video-toolbar">${btn('▶ Play mock introduction','video-play','','small')}<span id="video-time" class="tiny muted">0:00 / 0:12</span></div><progress id="video-progress" max="12" value="0" aria-label="Mock introduction playback"></progress><p class="tiny muted">Illustrative script by the demo author; these captions are not recorded speech.</p><div class="row between">${btn('Skip introduction','video-next','','ghost')}${btn('Continue to facts →','video-next','','primary')}</div>`);}
function toggleVideo(){if(videoPlaying){clearInterval(videoTimer);videoPlaying=false;}else{if(videoTick>=12)videoTick=0;videoPlaying=true;videoTimer=setInterval(()=>{if(modalStep!=='video'){stopMedia();return;}videoTick++;updateVideo();if(videoTick>=12){clearInterval(videoTimer);videoPlaying=false;updateVideo();}},1000);}updateVideo();}
function updateVideo(){const i=Math.min(3,Math.floor(videoTick/3));document.querySelector('#tev-frame').src=TEV_FRAMES[i];document.querySelector('#video-caption').textContent=INTRO_COPY[i];document.querySelector('#video-time').textContent='0:'+String(videoTick).padStart(2,'0')+' / 0:12';document.querySelector('#video-progress').value=videoTick;document.querySelector('[data-action="video-play"]').textContent=videoPlaying?'Ⅱ Pause':videoTick>=12?'↻ Replay mock introduction':'▶ Play mock introduction';}
document.querySelector('#onboarding-dialog').addEventListener('close',()=>{stopMedia();modalStep='';});
const OUTPUTS={brief:{prompt:'Make me a planning prep brief',title:'Your planning prep brief',body:`<p class="tiny muted">Canned example based on the demo conversation; it does not regenerate after edits.</p><h3>What I want to preserve</h3><p>This quarter held real momentum and serious frustration. A single rating should not flatten either side.</p><h3>What I want us to resolve</h3><p>A shared approach to AI building, governance, and prioritization—so we can move forward with confidence.</p><h3>A distinction worth making</h3><p>Wanting better evidence is compatible with acting now. We can agree on strategic bets while remaining honest about uncertainty.</p><h3>Questions to bring into the room</h3><ul><li>What agreement would remove the most friction around building with AI?</li><li>Which bets can we commit to now, and what evidence would change our minds?</li><li>How will we protect deep-work time while addressing the issues that need us together?</li></ul><h3>Leave room for a different view</h3><p>Where do my teammates see the situation differently? What might I be missing?</p><p class="small muted">Personal preparation, not new commitments or additions to your submitted answers.</p>`},tension:{prompt:'Help me name a tension',title:'Better evidence, without standing still',body:'<p>In this scripted example, wanting clearer causal evidence sits alongside a willingness to act. One question to explore: what would count as enough evidence for the next bet?</p><p class="small muted">A canned reflection prompt—not a conclusion about your current edits.</p>'},question:{prompt:'Give me a question for the room',title:'A question to bring into planning',body:'<p>“What shared agreement would let us move forward with confidence, even while some uncertainty remains?”</p><p class="small muted">Canned suggestion. Use it only if it reflects what you want to ask.</p>'}};
function afterChat(){const p=Model.currentPackage(state);if(!p)return review();return `${branchBack()}<section class="evaluation-box"><p class="eyebrow">Evaluate · Post-submit participant experience</p><h2>Questions about ongoing participant value</h2><ul><li>Would the personal takeaway make reflection valuable for the participant, too?</li><li>What would be the most useful takeaways?</li><li>Should we enable live chat after submission? For how long?</li></ul></section><div class="personal-chat"><header class="personal-chat-heading"><div><p class="eyebrow">Participant experience · After the interview</p><h1>Your Mirror</h1></div><span class="small muted">A space to keep thinking</span></header><div class="personal-log" role="log" aria-label="Personal follow-up conversation" aria-live="polite"><p class="chat-receipt">✓ Submission approved <span>Demo only · nothing sent</span></p><div class="bubble"><p class="speaker">MIRROR</p><p class="words">Your planning answers are ready. You chose exactly what to share.<br><br>What would help you now? We could pull together a planning prep brief, explore a tension, or find a question to bring into the room.</p><p class="small muted">What we discuss here stays separate from your approved submission.</p></div>${chatTurns.map((id,i)=>{const o=id==='copy'?{prompt:'Show my approved answers',title:'Your approved answers',body:packageHtml(p,false)+`<div class="row">${btn('Print this copy','print','','small')}${btn('Review or change answers','navigate','data-view="review"','ghost small')}</div>`}:OUTPUTS[id];return `<section class="personal-turn" id="personal-turn-${i}"><div class="bubble cary"><p class="speaker">${mockLabel()}</p><p class="words">${esc(o.prompt)}</p></div><div class="bubble mirror-response"><p class="speaker">MIRROR</p>${id==='copy'?'':`<h2>${esc(o.title)}</h2>`}${o.body}</div></section>`}).join('')}</div><div class="personal-composer"><p class="small">Continue the conversation</p><div class="prompt-chips">${Object.entries(OUTPUTS).map(([id,x])=>btn(esc(x.prompt),'chat-output',`data-output="${id}"`)).join('')}${btn('Show my approved answers','chat-output','data-output="copy"')}</div><p class="tiny muted">Choose a prompt to see a scripted example. No live AI or recording.</p></div></div>`;}
function about(){return `<div class="buyer-about"><p class="eyebrow">GoTu · Prototype walkthrough</p><h1>How the quarterly planning Mirror works.</h1><p class="lead">This demo covers the participant flow, approval boundary, and resulting planning outputs.</p><ol class="functional-overview" aria-label="Four stages of the quarterly planning Mirror"><li><div class="stage-marker"><span class="stage-number">1</span><span class="stage-label">Stage 1</span></div><strong>Establish context</strong><p>Confirm the participant, selected teams, and information available to the AI.</p></li><li><div class="stage-marker"><span class="stage-number">2</span><span class="stage-label">Stage 2</span></div><strong>Conduct one interview</strong><p>Cover the existing planning questions conversationally, with relevant follow-ups.</p></li><li><div class="stage-marker"><span class="stage-number">3</span><span class="stage-label">Stage 3</span></div><strong>Review and approve</strong><p>Let participants edit the complete draft and control exactly what gets shared.</p></li><li><div class="stage-marker"><span class="stage-number">4</span><span class="stage-label">Stage 4</span></div><strong>Use the outputs</strong><p>Give planners approved submissions and group synthesis; give participants a useful follow-up space.</p></li></ol><div class="row spacer">${btn('Start Demo','launch-demo','','primary')}<span class="small muted">Walk through the participant experience, then inspect both post-submit views.</span></div><section class="evaluation-box"><p class="eyebrow">Questions for the walkthrough</p><h2>What we need to evaluate</h2><ul><li>Does this seem likely to meet the “fuller, faster, funner” bar for participants compared with last cycle’s form?</li><li>What context should the AI receive?<ul><li>Should we incorporate each participant’s previous submission, when available?</li><li>Should we incorporate EOS or other shared background information?</li></ul></li><li>Does anything about the experience seem off-target or missing?</li></ul></section><details class="demo-explainer rule"><summary>How the demo works</summary><div><p>Start with the employee welcome, a simulated voice check, a short instruction page, and a mock introduction from Tev. Confirm the demo facts, then use “Show next turn” to walk through one continuous interview. Demo controls can explicitly stage remaining answers.</p><p>Review the complete draft, open an answer’s editing drawer, and approve the exact submission. A demo-only overview then separates the planning handoff from the participant’s personal follow-up space.</p><p class="small muted">Everything here is for evaluation. No employees will use this prototype. No live AI, recording, or delivery. Reset or reload clears local progress.</p><p class="small muted">Agent-authored reenactment using Cary’s historical answers and invented elaborations. These are not actual new statements or approvals. The demo combines Executive’s shared fields with distinct Executive and GTM assessments; it is not a historical combined submission. Email is fictional.</p><p class="small muted">Cold start: facts ground the interview. Prior submissions are authoring references, not runtime memory. The mock welcome video uses stills and authored captions, not recorded speech.</p></div></details></div>`;}
function welcome(){return `<div class="basics-page"><p class="eyebrow">GoTu · Quarterly planning Mirror</p><div class="onboard-progress"><span></span><span></span><span></span><span></span><span></span><span></span><small>Facts · before we talk</small></div><h1>Let’s get started.</h1><p class="lead">Tell us who you are and which offsites you’ll be attending. There are no right answers.</p><form id="intake" class="card document"><h2>Identity &amp; scope</h2><label for="name">Full name</label><input id="name" name="name" value="${esc(state.identity?.name||'Cary Gahm')}" required maxlength="200" ${state.identity?'disabled':''}><label for="email">Email address <span class="muted">(demo)</span></label><input id="email" name="email" type="email" value="${esc(state.identity?.email||'cary@example.com')}" required ${state.identity?'disabled':''}><fieldset ${state.identity?'disabled':''}><legend>Which team offsites are you representing?</legend><p class="tiny muted">The current Lovable form includes all nine options. This scripted walkthrough uses Executive and GTM.</p><div class="row" role="list" aria-label="Current Lovable team options"><label class="team-chip" role="listitem"><input type="checkbox" name="team" value="Executive" ${!state.identity||state.identity.teams.includes('Executive')?'checked':''}>Executive</label><label class="team-chip demo-option" role="listitem" title="Available in the live intake; inactive in this scripted demo"><input type="checkbox" disabled>Sales</label><label class="team-chip demo-option" role="listitem" title="Available in the live intake; inactive in this scripted demo"><input type="checkbox" disabled>Marketing</label><label class="team-chip demo-option" role="listitem" title="Available in the live intake; inactive in this scripted demo"><input type="checkbox" disabled>Operations</label><label class="team-chip demo-option" role="listitem" title="Available in the live intake; inactive in this scripted demo"><input type="checkbox" disabled>People Ops</label><label class="team-chip" role="listitem"><input type="checkbox" name="team" value="GTM" ${!state.identity||state.identity.teams.includes('GTM')?'checked':''}>GTM</label><label class="team-chip demo-option" role="listitem" title="Available in the live intake; inactive in this scripted demo"><input type="checkbox" disabled>Finance</label><label class="team-chip demo-option" role="listitem" title="Available in the live intake; inactive in this scripted demo"><input type="checkbox" disabled>Product</label><label class="team-chip demo-option" role="listitem" title="Available in the live intake; inactive in this scripted demo"><input type="checkbox" disabled>Engineering</label></div></fieldset><p class="tiny muted">Next, the Mirror covers last quarter, each selected team, and what matters next. No previous submission is loaded as interview memory.</p>${state.identity?btn('Begin Mirror','navigate','data-view="interview"','primary'):'<button class="primary" type="submit">Begin Mirror</button>'}</form></div>`;}
const MOCK_DETAIL='Agent-authored demonstration based on historical source answers, with invented elaborations. This is not a live interview, verified quotation, or actual participant approval. Nothing is recorded or sent.';
function mockLabel(staged=false){const detail=(staged?'This turn was staged explicitly to shorten the walkthrough. ':'')+MOCK_DETAIL;return `<span class="mock-label" tabindex="0" role="note" aria-label="${esc('Mock Data • Demo Purposes Only. '+detail)}">MOCK DATA <span class="mock-info" aria-hidden="true">i</span><span class="mock-tooltip" aria-hidden="true">${esc(detail)}</span></span>`;}
function interview(){
 if(!state.identity)return welcome();
 if(routeSection&&routeSection!==SLUGS[state.chapters[state.chapter]?.id]){const n=state.chapters.findIndex(c=>SLUGS[c.id]===routeSection);const names=state.chapters.slice(0,n+1).map(c=>c.name);return `<div class="conversation"><p class="eyebrow">Earlier in your conversation</p><h1>${esc(state.chapters[n]?.name||'Your interview')}</h1><p class="small muted">Your progress is kept. You’re viewing an earlier section.</p>${transcriptHtml(state.transcript.filter(t=>names.includes(t.chapter)))}${btn('Continue where I left off →','navigate','data-view="interview"','primary')}</div>`;}
 if(state.finished)return `<p class="eyebrow">One continuous interview</p><h1>Your reflection, in full.</h1><p class="lead">All topics are complete. Your answers are ready for a single final review.</p>${btn('Review my answers →','navigate','data-view="review"','primary')}<div class="spacer">${transcriptHtml(state.transcript)}</div>`;
 const c=state.chapters[state.chapter],t=c.turns[state.turn];
 const phase=t?.final?'One final question':t?.closing?'Before we move on':'';
 const current=t?`<div class="bubble current-question" aria-label="Current Mirror question"><p class="speaker">MIRROR${phase?' · '+esc(phase.toUpperCase()):''}</p><p class="words">${esc(t.q)}</p></div>`:`<div class="bubble current-question"><p class="speaker">MIRROR</p><p class="words">${state.chapter===state.chapters.length-1?'Thank you. Let’s look at your answers together.':'Thank you. Let’s keep going.'}</p></div>`;
 const nextStep=state.chapter===0&&state.turn===0?`<div class="section-next" role="note"><p><strong>Next:</strong> Choose “Show next turn” to play this question and the scripted response. Keep choosing it until the next-section button appears.</p></div>`:'';
 return `<div class="conversation"><div class="row between"><h1>${esc(c.name)}</h1><span class="pill">Section ${state.chapter+1} of ${state.chapters.length}</span></div><p class="muted small">One conversation. You’ll review all your answers at the end.</p>${nextStep}<div class="chapter-tabs" aria-label="Interview sections">${state.chapters.map((x,n)=>`<span class="${n===state.chapter?'current':''}">${n<state.chapter?'✓ ':''}${esc(x.name)}</span>`).join('')}</div><div class="chat-scroll" tabindex="0" aria-label="Interview transcript">${transcriptHtml(state.transcript)}${current}</div><div class="composer">${t?`<div class="row between">${btn('Show next turn →','respond','','primary')}<span class="tiny muted">Mock interview · no recording</span></div>`:btn(state.chapter===state.chapters.length-1?'Review all my answers →':'Continue to '+esc(state.chapters[state.chapter+1].name)+' →','next','','primary')}<details class="demo-controls"><summary>Demo controls · skip ahead</summary><div class="stack"><p class="tiny muted">Explicitly stage scripted answers to shorten the walkthrough. Nothing is inferred.</p>${t?btn('Stage remaining answers in this section','stage-section','','small'):''}${btn('Stage rest of interview → final review','stage-all','','small')}</div></details></div></div>`;
}
function transcriptHtml(items){let prev='';return items.map(t=>{const divider=t.chapter!==prev?`<div class="chapter-divider">${esc(t.chapter)}</div>`:'';prev=t.chapter;return divider+`<div class="bubble"><p class="speaker">MIRROR${t.final?' · LAST FOLLOW-UP':t.closing?' · SECTION CLOSE':''}</p><p class="words">${esc(t.q)}</p></div><div class="bubble cary"><p class="speaker">${mockLabel(t.staged)}</p><p class="words">${esc(t.a)}</p></div>`;}).join('');}

let panelId=null,panelMode='view',panelInitial='';
const drawer=()=>document.querySelector('#answer-drawer');
function drawPanel(){
 const a=state.answers.find(x=>x.id===panelId);if(!a)return;const n=REVIEW_NOTES[a.id],d=discussionFor(a),editing=!!state.editing;
 drawer().innerHTML=`<header class="drawer-head"><div><p class="eyebrow">${esc(a.group)}</p><h2 id="drawer-title" tabindex="-1">${esc(a.label)}</h2></div>${btn('×','panel-close','aria-label="Close answer panel"','ghost')}</header><div class="drawer-body"><p class="question">${esc(a.question)}</p>${!editing?`<details class="current-wording" ${panelMode==='suggestion'?'':'open'}><summary>Current submission wording</summary><div><p class="answer">${esc(a.text)}</p></div></details>${a.flag?`<section class="drawer-suggestion"><p class="eyebrow">Optional suggestion</p><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p>${btn('Edit using this suggestion','panel-use',`data-id="${a.id}"`,'primary')}<details class="spacer"><summary>Compare suggested wording</summary><div><p class="answer">${esc(n.suggestion)}</p><p class="small muted">${esc(n.explanation)}</p></div></details>${btn('Keep my wording','panel-keep',`data-id="${a.id}"`,'ghost')}</section>`:''}<details class="answer-context"><summary>Conversation & original draft</summary><div><p class="small muted">Private context · excluded from the submission</p><p class="answer">${esc(a.original)}</p>${transcriptHtml(state.transcript.filter(t=>t.fields.includes(a.id)))}${a.discussion.map(x=>`<p class="answer">${esc(x.question)}<br>${esc(x.response)}</p>`).join('')}</div></details>`:`${panelMode==='discuss'?`<div class="drawer-suggestion"><p class="eyebrow">Talk it through · scripted</p><p>${esc(d.q)}</p>${discussionStep?`<p class="answer">${esc(d.a)}</p>`:btn('Show clarification','panel-clarify',`data-id="${a.id}"`)}</div>`:''}<label for="edit-text">Your wording</label>${editorControl(a,panelInitial)}<p class="tiny muted">Save updates the document. It does not approve or submit it.</p>`}<p id="panel-status" role="status" class="small"></p></div><footer class="drawer-footer">${editing?`${btn('Save changes','panel-save',`data-id="${a.id}"`,'primary')}${btn('Cancel edit','panel-cancel','','ghost')}${panelMode==='edit'?btn('Talk it through','panel-discuss','','ghost small'):''}`:`${btn('Edit wording','panel-edit',`data-id="${a.id}"`,'primary')}${btn('Talk it through','panel-discuss',`data-id="${a.id}"`,'ghost')}`}</footer>`;
}
function openPanel(id,mode='view'){panelId=id;panelMode=mode;drawPanel();drawer().showModal();document.querySelector('#drawer-title').focus();}
function beginPanelEdit(mode,text){const a=state.answers.find(x=>x.id===panelId);panelMode=mode;discussionStep=0;state=Model.reduce(state,{type:mode==='discuss'?'discuss':'edit',id:panelId});panelInitial=text??a.text;render();drawPanel();document.querySelector('#edit-text')?.focus();}
function closePanel(force=false){const input=document.querySelector('#edit-text');if(!force&&state.editing&&input&&input.value!==panelInitial&&!confirm('Discard your unsaved wording changes?'))return;const id=panelId;if(state.editing)state=Model.reduce(state,{type:'cancel'});drawer().close();panelId=null;render();document.querySelector('#answer-'+id+' button')?.focus({preventScroll:true});}
function branchBack(){return `<div class="branch-back">${btn('← Two outcomes','navigate','data-view="outcomes"','ghost')}<span class="tiny muted">Demo navigation</span></div>`;}
function outcomes(){const p=Model.currentPackage(state);return `<div class="outcome-page"><p class="eyebrow">Demo overview · Beyond the interview</p><h1>One reflection.<br>Two useful outcomes.</h1><p class="lead">The participant has reviewed and approved ${p.answers.length} answers. Now look at what each side gets.</p><p class="small muted">This is a demo overview, not an employee screen. No submission has actually been sent.</p><div class="outcome-grid"><article><span class="eyebrow">01 · The planning handoff</span><h2>What the planning team gets</h2><p>Participant-approved answers and cross-group themes, ready for the planning process.</p><ul><li>One row per person–team; all sixteen columns.</li><li>Facilitator questions synthesized from anonymized group input.</li><li>No private chat, rejected wording, or review notes.</li></ul>${btn('Explore the planning handoff →','navigate','data-view="tev"','primary')}</article><article><span class="eyebrow">02 · Their personal value</span><h2>What the participant gets</h2><p>A copy of what they chose to share, plus space to make their reflection useful to them.</p><ul><li>The exact approved submission.</li><li>A personal preparation brief or a question for the room.</li><li>Further exploration kept separate from the handoff.</li></ul>${btn('Explore participant experience →','navigate','data-view="chat"','primary')}</article></div><div class="rule"><p class="small muted">Want to revisit the trust boundary? Edit an approved answer and see the package retire.</p>${btn('Return to review','navigate','data-view="review"','ghost')}</div></div>`;}
function forTev(){return `${branchBack()}<p class="eyebrow">Planning team · Approved handoff</p><h1>Richer input.<br>A room-ready synthesis.</h1><p class="lead">The planning team can inspect approved submissions, then use anonymized group themes to decide what the room should resolve.</p><section class="evaluation-box"><p class="eyebrow">Evaluate · Post-submit planner experience</p><h2>Questions for the planning team</h2><ul><li>Is the approved handoff useful for running planning?</li><li>What would be the most helpful way to provide the submissions?</li><li>Which thematic or other analyses would be most helpful as a starting point?</li><li>Would chatting with the submissions be helpful?</li></ul></section><div class="outcome-grid three"><article><h2>Group themes & questions</h2><p>See how facilitator questions emerge from patterns and tensions across everyone’s anonymized input.</p>${btn('Open group briefing →','navigate','data-view="group"','primary')}</article><article><h2>The approved spreadsheet</h2><p>Inspect this participant’s two team rows, filter the view, and download the exact approved values.</p>${btn('Open spreadsheet →','navigate','data-view="sheet"','primary')}</article><article><h2>From form to conversation</h2><p>Review the recommended interview guide: familiar questions, natural openings, and purposeful follow-ups.</p>${btn('Read the proposed guide →','navigate','data-view="guide"','primary')}</article></div><p class="small muted rule">The group briefing is a historical, anonymized demonstration. It synthesizes patterns; it does not repeat or attribute individual questions.</p>`;}
const GROUP_THEMES=[
 {title:'A usable path for AI building decisions',signals:'Across the group, related concerns appeared as requests for clearer permitted scope, risk checks, decision authority, and a reusable approval path. The inputs support a shared need for clarity, but not agreement on one control model.',question:'Walk one plausible AI proposal through the rules. Where could competent teams still reach different answers?',caution:'Do not reduce the input to “pro-AI” versus “anti-AI.” The group raised distinct operating questions.'},
 {title:'Decision rights that survive disagreement',signals:'The group described circular issue discussions, defensive debate, unclear decision ownership, and uncertainty about whether the right issues reach the room. Other team input reported openness and cohesion, so the pattern is not a company-wide culture verdict.',question:'For one contested decision, who must agree, who must be heard, and who can commit us?',caution:'Separate the decision process from any interpersonal repair the specific issue may require.'},
 {title:'Portfolio choices with cross-team consequences',signals:'Across teams, people named parallel growth, product, efficiency, and campaign ambitions that can draw on the same capacity. The input identifies possible collisions and dependencies; it does not prove which initiative should win.',question:'If we protect this outcome, what will we do less of—and have the affected teams agreed?',caution:'Leave with an explicit tradeoff and a confirmed cross-team handoff, not another list of aspirations.'}
];
function groupBrief(){return `${branchBack()}<div class="group-brief"><p class="eyebrow">Planning team · Anonymized group synthesis</p><h1>Questions the whole group’s input earns.</h1><p class="lead">These facilitator questions combine corroborating and differing signals across the complete historical demo set. They do not repeat one person’s submitted question.</p><div class="group-scope" aria-label="Historical synthesis scope"><div><strong>39</strong><span>anonymized contributors</span></div><div><strong>54</strong><span>distinct person–team pairs</span></div><div><strong>9</strong><span>team labels represented</span></div></div><div class="notice"><strong>Historical demonstration, not a current-cycle finding.</strong><p>All relevant business fields across 55 export rows were included in the synthesis pass. A theme can be important without being unanimous. Identities and source wording are omitted from this facilitator view.</p></div>${GROUP_THEMES.map((theme,i)=>`<article class="theme-card"><p class="eyebrow">Group theme · ${String(i+1).padStart(2,'0')}</p><h2>${esc(theme.title)}</h2><p class="theme-signals"><strong>Synthesized signals:</strong> ${esc(theme.signals)}</p><div class="facilitator-question"><span class="eyebrow">Ask in the room</span><p>“${esc(theme.question)}”</p></div><p class="small muted"><strong>Preserve the nuance:</strong> ${esc(theme.caution)}</p></article>`).join('')}<div class="row spacer">${btn('← Planning handoff','navigate','data-view="tev"','ghost')}${btn('Inspect participant spreadsheet','navigate','data-view="sheet"')}</div></div>`;}
const GUIDE=[
 ['Looking back','Personal Best','Personal best from the last 90 days','What’s one win outside work that meant a lot to you in the last 90 days?','If the significance is unclear: “What made that matter to you?”','One personal best; retain the 90-day window.'],
 ['Looking back','Professional Best','Professional best from the last 90 days','At work, what’s the win you’re most proud of from those 90 days?','If only an initiative is named: “What changed because of that?”','One work win; separate from personal best.'],
 ['Looking back','Quarter Rating; Rating Reason','Rate last quarter 1–10; biggest reason','What number would you give the quarter—1 is rough, 10 exceptional? What’s the biggest reason?','If the explanation complicates the number: “What would someone miss if they saw only the rating?”','Explicit whole number, 1–10. Preserve nuance in the separate reason; confirm discrepancies at review.'],
 ['Each selected team','EOS Component; EOS Example','EOS area needing improvement; one example','Thinking just about this team, which EOS area needs attention? What happened that brings it to mind?','Offer all six labels: Vision, People, Data, Issues, Process, Traction. Clarify the intended area if needed.','One selected EOS label and a distinct concrete example, per team.'],
 ['Each selected team','Avoided Conversation','Conversation the team may be avoiding','What does this team need to talk about that keeps getting left unsaid?','If the issue is named without the conversation: “What would you want us to say out loud?”','Preserve the concern and intended discussion; do not soften disagreement automatically.'],
 ['Each selected team','Biggest Issue','Single biggest issue limiting the team','If you could name one thing holding this team back, what would it be?','If several compete: “Which is the biggest constraint right now?”','One priority issue, distinct for each team.'],
 ['Looking forward','Success Vision (90 days)','What would be true after a wildly successful quarter?','Picture us 90 days from now, with a quarter that went really well. What’s different?','If abstract: “What would you notice that tells you we got there?”','Person-level success vision, shared across team rows.'],
 ['Looking forward','Top Rock','Most important Rock to make that happen','To make that future happen, what’s the one Rock you’d put first?','If only a theme: “What would completing that look like?”','One proposed Rock. Do not invent an owner, deadline, or commitment.'],
 ['Looking forward','Issues List','Anything else for the Issues List','Before we finish, what else should go on the Issues List? Nothing else is a valid answer.','Clarify only if an item’s meaning is unclear.','Person-level list, or an explicit none; shared across team rows.']
];
function interviewGuide(){return `${branchBack()}<p class="eyebrow">Planning team · Recommended adaptation</p><h1>Keep the questions.<br>Open up the conversation.</h1><p class="lead">A coverage guide, not a script to recite. Let people tell the story, then check that the familiar planning answers are there.</p><div class="guide-rules"><h2>How the interviewer would work</h2><p>Start with name, email, and teams. Move through looking back, each selected team, and looking forward. Use what the participant has already said; don’t ask them to repeat answers.</p><p>Ask one natural question at a time; split paired openings below into successive turns. Follow up where meaning or required detail is missing. At a section’s end, allow at most one final substantive follow-up, then ask: “Before we move on, what else would you like me to understand?”</p><p>Review the complete set at the end. Offer optional suggestions using the whole conversation, preserve uncertainty and disagreement, and let the participant approve the exact text.</p><p class="tiny muted">Follow-ups below are examples, not a mandatory checklist. This recommendation is for this cycle; the demo’s responses remain scripted.</p></div>${GUIDE.map((r,i)=>`<article class="guide-entry"><p class="eyebrow">${esc(r[0])} · ${String(i+1).padStart(2,'0')}</p><h2>${esc(r[2])}</h2><div class="guide-columns"><div><p class="tiny muted">CONVERSATIONAL OPENING</p><p class="guide-question">“${esc(r[3])}”</p><p class="small"><strong>Follow the answer:</strong> ${esc(r[4])}</p></div><div><p class="tiny muted">WHAT THE HANDOFF MUST RETAIN</p><p>${esc(r[5])}</p><p class="small muted">Spreadsheet: ${esc(r[1])}</p></div></div></article>`).join('')}<section class="guide-rules"><h2>The same sixteen columns</h2><p>Submitted At records package time. Full Name, Email, and Teams come from intake. Team identifies each row. The four team-assessment columns vary per team; the seven person-level answers repeat.</p><p class="small">${HEADERS.map(esc).join(' · ')}</p><p class="tiny muted">Source: locally downloaded Lovable prework form, Context & Look Back, Team Assessment, and Looking Forward. Quarter labels adapt to the current cycle; the 90-day windows remain.</p></section>${btn('Back to the planning handoff','navigate','data-view="tev"','ghost')}`;}

function review(){
 if(!state.finished)return interview();
 const notes=state.answers.filter(a=>a.flag),p=Model.currentPackage(state);
 return `<div class="review-document"><p class="experience-label">Participant experience · review before sharing</p><div class="review-intro"><p class="eyebrow">Your planning submission</p><h1>Make sure this sounds like you.</h1><p class="lead">Read your answers as one document. Open any answer to edit it or explore a suggestion.</p><p class="small muted">Only this document and your name, email, and teams go to the planning team. Your conversation and review discussions stay out.</p></div><section class="evaluation-box"><p class="eyebrow">Evaluate · Post-interview review</p><h2>Questions about participant control</h2><ul><li>Can you see exactly how participants control what reaches the planning team?</li><li>Is the distinction between private conversation, draft answers, and the approved submission clear?</li><li>Does this review provide enough control without making the experience feel burdensome?</li></ul></section><div class="review-overview"><span><strong>${state.answers.length} answers</strong> · ${notes.length} optional suggestions</span>${btn('Go to approval ↓','approval-anchor','','ghost small')}</div><div class="submission-paper"><div class="paper-meta"><strong>${esc(state.identity.name)}</strong><span>${esc(state.identity.teams.join(' · '))}</span><span class="small muted">${esc(state.identity.email)} · ${p?'Approved copy':'Draft for your review'}</span></div><nav class="review-jumps" aria-label="Review sections">${groupOrder().map((g,i)=>btn(esc(g),'jump-group',`data-group="group-${i}"`)).join('')}</nav>${groupOrder().map((group,i)=>`<section class="review-group" id="group-${i}"><h2>${esc(group)} <span class="tiny muted">${['Executive','GTM'].includes(group)?'This team':'Shared across teams'}</span></h2>${state.answers.filter(a=>a.group===group).map(answerCard).join('')}</section>`).join('')}</div><section class="review-finish" id="approval-section" tabindex="-1"><p class="eyebrow">One final decision</p><h2>Ready to share these answers?</h2><p>Approving creates the exact copy for the planning team and for you. Suggestions are optional.</p><label class="check"><input type="checkbox" id="all-reviewed"><span>I’ve read this document. It says what I want to share.</span></label><div class="row spacer">${btn('Approve this submission →','approve-finish','id="approve-finish" disabled','primary')}</div><p class="tiny muted spacer">Demo only. Nothing is sent. Changing an answer requires fresh approval.</p></section></div>`;
}
function answerCard(a){const label=Model.isApproved(a)?'Approved':a.choice;return `<article class="answer-card" id="answer-${a.id}" data-answer="${a.id}" tabindex="-1"><div class="answer-heading"><h3>${esc(a.label)}</h3><div class="row">${label?`<span>${esc(label)}</span>`:''}${btn('Edit','open-answer',`data-id="${a.id}" aria-label="Edit ${esc(a.label)} — ${esc(a.group)}"`,'ghost small')}</div></div><p class="answer">${esc(a.text)}</p>${a.id==='rating'?'<p class="tiny muted">1 — Rough · 10 — Exceptional</p>':''}${a.flag?btn('✧ '+esc(REVIEW_NOTES[a.id].title),'open-suggestion',`data-id="${a.id}"`,'suggestion-link'):''}</article>`;}

function editorControl(a,text){return a.kind==='rating'?`<input id="edit-text" type="number" min="1" max="10" step="1" value="${esc(text)}">`:a.kind==='component'?`<select id="edit-text">${EOS.map(x=>`<option ${text===x?'selected':''}>${x}</option>`).join('')}</select>`:`<textarea id="edit-text">${esc(text)}</textarea>`;}
function discussionFor(a){
 if(a.id==='GTM-example')return {q:'What should come through more clearly in this answer?',a:'I’m ready to move. I want to understand what is driving the results, and keep the uncertainty without making it sound like hesitation.',draft:DISCUSSION_DATA};
 if(a.id==='GTM-avoided')return {q:'What do you most want people to understand about “politicking”?',a:'Keep the concern about internal politics. I don’t mean “communicate better.” I want us to put this team first, agree on the bets, and go.',draft:POLITICS_REVISION};
 if(a.id==='reason')return {q:'How do you want to explain the difference between 6 and six and a half?',a:'Keep 6 on the whole-number scale. Explain that my overall feeling was six and a half. Don’t lose either the excitement or the frustration.',draft:RATING_REVISION};
 return {q:'What would you like to change or make clearer?',a:'I want to keep the meaning and edit the wording myself.',draft:a.text};
}
function answer(){return review();}
function renderAt(id){const before=document.querySelector('[data-answer="'+id+'"]')?.getBoundingClientRect().top;render();const card=document.querySelector('[data-answer="'+id+'"]');if(card&&before!==undefined)window.scrollBy(0,card.getBoundingClientRect().top-before);return card;}
function complete(){const p=Model.currentPackage(state);if(!p)return review();return `${branchBack()}<div class="completion"><div class="checkmark" aria-hidden="true">✓</div><p class="eyebrow">Your approved reflection</p><h1>Ready to bring into the room.</h1><p class="lead">You’ve chosen what you want to say. Your approved answers are gathered into a copy you can keep.</p><div class="notice success"><strong>Demo package ready. Nothing has been delivered.</strong><p class="small">${esc(p.identity.name)} · ${esc(p.identity.teams.join(' + '))}<br>${p.answers.length} approved answers · ${p.rows.length} spreadsheet rows</p></div><div class="row spacer">${btn('Print my approved copy','print','','primary')}${btn('Preview approved copy','preview-print')}${btn('Back to personal space','navigate','data-view="chat"','ghost')}</div><details class="spacer"><summary>Exact approved package</summary><div>${packageHtml(p,false)}</div></details><div class="rule"><p class="small muted">Need to change something? Editing clears that answer’s approval and retires this local package.</p>${btn('Return to final review','navigate','data-view="review"')}</div><div id="copy-preview"></div></div>`;}
function sheet(){const p=Model.currentPackage(state);if(!p)return review();const rows=p.rows.filter(r=>teamFilter==='All teams'||r[8]===teamFilter);return `${branchBack()}<p class="eyebrow">Illustrated handoff · Planning team</p><h1>The same answers.<br>A familiar spreadsheet.</h1><p class="lead">Filter by team, bring issues into the meeting, and review proposed Rocks. Every cell below comes from the approved package.</p><div class="notice"><strong>Local illustration, not a new facilitator application.</strong><p>Nothing has been delivered. This preview contains no conversation, rejected drafts, or advisory flags.</p></div><div class="row between spacer"><div><label for="team-filter">Team</label><select id="team-filter"><option>All teams</option>${p.identity.teams.map(t=>`<option ${t===teamFilter?'selected':''}>${t}</option>`).join('')}</select></div><div class="row">${btn('Download CSV · all teams','csv','','primary')}${btn('Inspect CSV text','csv-preview')}</div></div><span class="tiny muted">${rows.length} of ${p.rows.length} rows · 16 unchanged columns · scroll horizontally →</span><div class="sheet-wrap" tabindex="0" aria-label="Approved spreadsheet"><table class="sheet"><thead><tr>${HEADERS.map((h,i)=>`<th scope="col">${String.fromCharCode(65+i)} · ${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td><p>${esc(v)}</p></td>`).join('')}</tr>`).join('')}</tbody></table></div>${csvVisible?`<label for="csv-text">Exact CSV download contents</label><textarea id="csv-text" readonly>${esc(Model.csv(p))}</textarea>`:''}<div class="card"><p class="eyebrow">Facilitator preparation</p><h2>Move from rows to group themes.</h2><p>Questions for the room are synthesized from everyone’s anonymized input, including corroborating and differing signals. They are not copied from this participant.</p>${btn('Open group themes & questions →','navigate','data-view="group"','primary')}</div><div class="row spacer">${btn('← Planning handoff','navigate','data-view="tev"','ghost')}${btn('Edit an answer to explore approval invalidation','navigate','data-view="review"')}</div>`;}
function packageHtml(p,print){return `<h${print?'1':'2'}>GoTu · Approved planning reflection</h${print?'1':'2'}><p class="print-meta"><strong>SIMULATED DEMO — NOT DELIVERED</strong><br>${esc(p.identity.name)} · ${esc(p.identity.email)}<br>Teams: ${esc(p.identity.teams.join('; '))}<br>Local package timestamp: ${esc(p.at)}</p>${['Looking back',...p.identity.teams,'Looking forward'].map(g=>`<section class="print-section"><h2>${esc(g)}</h2>${p.answers.filter(a=>a.group===g).map(a=>`<div class="print-field"><h3>${esc(a.label)}</h3><p class="inline-text">${esc(a.text)}</p></div>`).join('')}</section>`).join('')}`;}
function updatePrint(){const p=Model.currentPackage(state);document.querySelector('#print-root').innerHTML=p?packageHtml(p,true):'<h1>No approved package yet</h1><p>Complete final review before printing. Conversation and draft answers are excluded.</p>';}
function stageSection(){if(state.finished)return;const c=state.chapters[state.chapter];while(state.turn<c.turns.length)state=Model.reduce(state,{type:'answer',staged:true});}
document.addEventListener('submit',e=>{if(e.target.id!=='intake')return;e.preventDefault();const f=new FormData(e.target);const teams=f.getAll('team');if(!f.get('name').trim()){document.querySelector('#toast').textContent='Enter a name.';return;}if(!teams.length){state.notice='Select at least one team.';const el=document.querySelector('#toast');el.textContent=state.notice;return;}state=Model.reduce(state,{type:'start',identity:{name:f.get('name').trim(),email:f.get('email').trim(),teams}});routeSection=null;view='interview';render();main.focus();window.scrollTo(0,0);});
document.addEventListener('change',e=>{if(e.target.id==='all-reviewed')document.querySelector('#approve-finish').disabled=!e.target.checked||!!state.editing;if(e.target.id==='team-filter'){teamFilter=e.target.value;render();}});
document.addEventListener('click',e=>{
 const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;
 const action=b.dataset.action,id=b.dataset.id;

 if(action==='open-answer'||action==='open-suggestion'){openPanel(id,action==='open-suggestion'?'suggestion':'view');if(action==='open-answer')beginPanelEdit('edit');return;}
 if(action==='approval-anchor'){document.querySelector('#approval-section').scrollIntoView({block:'start'});document.querySelector('#approval-section').focus({preventScroll:true});return;}
 if(action==='panel-close'||action==='panel-cancel'){closePanel();return;}
 if(action==='panel-edit'){beginPanelEdit('edit');return;}
 if(action==='panel-discuss'){const input=document.querySelector('#edit-text');if(input&&input.value!==panelInitial&&!confirm('Discard unsaved edits and explore a scripted clarification?'))return;beginPanelEdit('discuss');return;}
 if(action==='panel-use'){beginPanelEdit('edit',REVIEW_NOTES[panelId].suggestion);return;}
 if(action==='panel-keep'){state=Model.reduce(state,{type:'keep',id:panelId});closePanel(true);return;}
 if(action==='panel-clarify'){const d=discussionFor(state.answers.find(a=>a.id===panelId));state=Model.reduce(state,{type:'clarification',id:panelId,question:d.q,response:d.a});discussionStep=1;panelInitial=d.draft;drawPanel();document.querySelector('#edit-text').focus();return;}
 if(action==='panel-save'){const text=document.querySelector('#edit-text').value,a=state.answers.find(x=>x.id===panelId);if(!Model.valid({...a,text})){document.querySelector('#panel-status').textContent='Enter an answer. Ratings must be whole numbers from 1 to 10.';return;}state=Model.reduce(state,{type:'save',id:panelId,text});closePanel(true);return;}
 if(action==='navigate'){navigate(b.dataset.view);return;}
 if(action==='launch-demo'){if(state.identity&&!confirm('Start the first-time walkthrough again? This clears this demo’s edits and approvals.'))return;state=Model.initial();teamFilter='All teams';csvVisible=false;discussionStep=0;expandedSuggestion=null;selectedOutput=null;chatTurns=[];navigate('initializing');return;}
 if(action==='begin-onboarding'){openMic();return;}
 if(action==='mic-test'){runMic();return;}
 if(action==='mic-stop'||action==='mic-skip'){navigate('voice');return;}
 if(action==='voice-next'){openVideo();return;}
 if(action==='video-play'){toggleVideo();return;}
 if(action==='video-next'){closeOnboarding();navigate('welcome');return;}
 if(action==='close-onboarding'){closeOnboarding();return;}
 if(action==='chat-output'){if(!Model.currentPackage(state))return;chatTurns.push(b.dataset.output);render();const log=document.querySelector('.personal-log'),turn=log.querySelector('.personal-turn:last-child');if(turn)log.scrollTop+=turn.getBoundingClientRect().top-log.getBoundingClientRect().top-16;return;}
 if(action==='reset'){if(state.identity&&!confirm('Reset this local demo? In-memory edits and approvals will be cleared.'))return;stopCountdown();closeOnboarding();routeSection=null;selectedOutput=null;chatTurns=[];state=Model.initial();view='about';teamFilter='All teams';csvVisible=false;discussionStep=0;expandedSuggestion=null;render();main.focus();window.scrollTo(0,0);return;}
 if(action==='respond'){dispatch({type:'answer'});return;}
 if(action==='stage-section'){stageSection();render();return;}
 if(action==='stage-all'){while(!state.finished){stageSection();state=Model.reduce(state,{type:'next'});}view='review';render();main.focus();window.scrollTo(0,0);return;}
 if(action==='next'){routeSection=null;state=Model.reduce(state,{type:'next'});if(state.finished)view='review';render();return;}
 if(action==='jump-answer'){document.querySelector('#answer-'+id)?.scrollIntoView({block:'start'});return;}
 if(action==='jump-group'){document.querySelector('#'+b.dataset.group)?.scrollIntoView({block:'start'});return;}
 if(action==='toggle-suggestion'){expandedSuggestion=expandedSuggestion===id?null:id;renderAt(id);return;}
 if(action==='keep'){state=Model.reduce(state,{type:'keep',id});expandedSuggestion=null;renderAt(id);return;}
 if(action==='edit'||action==='discuss'){if(state.editing)return;focusId=id;discussionStep=0;expandedSuggestion=null;state=Model.reduce(state,{type:action,id});renderAt(id);document.querySelector('#edit-text')?.focus({preventScroll:true});return;}
 if(action==='discuss-response'){discussionStep=1;const d=discussionFor(selected());state=Model.reduce(state,{type:'clarification',id,question:d.q,response:d.a});renderAt(id);return;}
 if(action==='save'){const text=document.querySelector('#edit-text').value;const a=state.answers.find(a=>a.id===id);if(!Model.valid({...a,text})){document.querySelector('#toast').textContent='Enter an answer. Ratings must be whole numbers 1–10.';document.querySelector('#edit-text').focus();return;}state=Model.reduce(state,{type:'save',id,text});renderAt(id)?.focus({preventScroll:true});return;}
 if(action==='cancel'){state=Model.reduce(state,{type:'cancel'});renderAt(id)?.focus({preventScroll:true});return;}
 if(action==='suggest'){state=Model.reduce(state,{type:'edit',id});state=Model.reduce(state,{type:'save',id,text:REVIEW_NOTES[id].suggestion});expandedSuggestion=null;renderAt(id)?.focus({preventScroll:true});return;}
 if(action==='original'){state=Model.reduce(state,{type:'original',id});renderAt(id);return;}
 if(action==='approve'){dispatch({type:'approve',id});return;}
 if(action==='approve-finish'){
  if(!document.querySelector('#all-reviewed')?.checked||state.editing)return;
  state=Model.reduce(state,{type:'approveAll'});state=Model.reduce(state,{type:'package',at:new Date().toISOString()});
  if(Model.currentPackage(state)){selectedOutput=null;chatTurns=[];view='outcomes';render();main.focus();window.scrollTo(0,0);}return;
 }
 if(action==='package'){state=Model.reduce(state,{type:'package',at:new Date().toISOString()});if(Model.currentPackage(state)){selectedOutput=null;chatTurns=[];view='outcomes';render();main.focus();window.scrollTo(0,0);}return;}
 const p=Model.currentPackage(state);if(!p)return;
 if(action==='print'){updatePrint();window.print();return;}
 if(action==='preview-print'){document.querySelector('#copy-preview').innerHTML='<div class="card spacer">'+packageHtml(p,false)+'</div>';document.querySelector('#copy-preview').scrollIntoView({behavior:'instant'});return;}
 if(action==='csv-preview'){csvVisible=!csvVisible;render();return;}
 if(action==='csv'){const blob=new Blob([Model.csv(p)],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='gotu-approved-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);state.notice='CSV downloaded locally. Nothing was delivered.';render();}
});
document.addEventListener('toggle',e=>{if(e.target.matches?.('.demo-controls')&&e.target.open)e.target.scrollIntoView({block:'nearest',behavior:'instant'});},true);
document.querySelector('#answer-drawer').addEventListener('keydown',e=>{if(e.key!=='Tab')return;const d=drawer(),items=[...d.querySelectorAll('button,input,textarea,select,summary,a[href],[tabindex="0"]')].filter(x=>!x.disabled&&x.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.id==='drawer-title')){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}});
document.querySelector('#answer-drawer').addEventListener('cancel',e=>{e.preventDefault();closePanel();});
window.addEventListener('beforeprint',updatePrint);
readRoute();
